INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES
('how-to-ask-for-help', 'How to ask for help', NULL, 'Master the art of asking technical questions that get helpful responses', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When you are asking a bunch of strangers for help on the internet, there are tricks to get people to be more willing to help you."}]},{"type":"paragraph","content":[{"type":"text","text":"Unless you are paying for support, you need to make it as easy as possible for volunteers to help you."}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s some advice to help people help you."}]},{"type":"heading","attrs":{"level":2,"id":"make-it-easy-to-read"},"content":[{"type":"text","text":"Make it Easy to Read"}]},{"type":"paragraph","content":[{"type":"text","text":"Learn the system you''re writing on so you can convey the information clearly. Having to read badly formatted text is not a nice introduction to your problem."}]},{"type":"paragraph","content":[{"type":"text","text":"Separate your question from the log outputs, most systems will have a way to enter code. Use that code format for logs, code, config, etc. Keep each type of sample separate, or at least spaced out well enough, with a comment to show what it is."}]},{"type":"heading","attrs":{"level":3,"id":"example"},"content":[{"type":"text","text":"Example"}]},{"type":"codeBlock","attrs":{"language":"plaintext","title":"dmesg log with error","meta":null},"content":[{"type":"text","text":"[331337.438088] hub 4-0:1.0: 2 ports detected\n[331337.465300] ACPI: bus type thunderbolt registered\n[331337.612428] thunderbolt 0000:08:00.0: 0: DROM device_rom_revision 0x0 unknown\n[331337.613424] thunderbolt 0-0: ignoring unnecessary extra entries in DROM\n[331342.334285] ieee80211 phy0: brcmf_inetaddr_changed: fail to get arp ip table err:-52\n[331357.956017] xhci_hcd 0000:3e:00.0: Unable to change power state from D3cold to D0, device inaccessible\n[331357.956034] xhci_hcd 0000:3e:00.0: Controller not ready at resume -19\n[331357.956035] xhci_hcd 0000:3e:00.0: PCI post-resume error -19!\n[331357.956037] xhci_hcd 0000:3e:00.0: HC died; cleaning up\n# partial results from lspci\n00:1c.0 PCI bridge: Intel Corporation 100 Series/C230 Series Chipset Family PCI Express Root Port #1 (rev f1)\n00:1c.1 PCI bridge: Intel Corporation 100 Series/C230 Series Chipset Family PCI Express Root Port #2 (rev f1)"}]},{"type":"heading","attrs":{"level":2,"id":"reproducible-issue"},"content":[{"type":"text","text":"Reproducible Issue"}]},{"type":"paragraph","content":[{"type":"text","text":"Where possible create a minimal reproduction of the issue. This lets people try recreate the issue with your config and prevents you from leaking secrets that might need to stay secret."}]},{"type":"paragraph","content":[{"type":"text","text":"Unless you are certain the problem exists in just one file, make people''s lives easier by giving as much info as possible."}]},{"type":"paragraph","content":[{"type":"text","text":"The best way to do that is a cut down, reproducible sample."}]},{"type":"heading","attrs":{"level":2,"id":"explain-environment"},"content":[{"type":"text","text":"Explain Environment"}]},{"type":"paragraph","content":[{"type":"text","text":"Explain the environment you are running in, it may well be an environmental issue you are facing. Things like what hardware, software and config (where you can) it''s running - i.e. Docker version 24.0.2, build cb74dfcd85 on a laptop running Debian 11.7 stable, an AWS VM "},{"type":"text","marks":[{"type":"code"}],"text":"m7g.large"},{"type":"text","text":" running Amazon Linux, etc."}]},{"type":"heading","attrs":{"level":2,"id":"make-it-quick--easy-for-people"},"content":[{"type":"text","text":"Make it Quick & Easy for People"}]},{"type":"paragraph","content":[{"type":"text","text":"Be conscious of the amount of time people have to spend to get up to speed. This ties in with the reproducible sample. Don''t post a link to an instruction you followed. If you do that and nothing else you are expecting people to read through that article which takes precious time. Even after reading it, unless there is an obvious mistake in the article, it may not assist you as chances are you''ve done something different to the article. Maybe you missed a step, maybe you made a typo, used different hosting options, used different versions of software. Feel free to add that you followed an article, but don''t expect people helping you to have to read that article before getting started."}]},{"type":"heading","attrs":{"level":2,"id":"explain-your-steps-so-far"},"content":[{"type":"text","text":"Explain Your Steps so Far"}]},{"type":"paragraph","content":[{"type":"text","text":"State what you have tried and what you think it might be, there is nothing less rewarding than helping someone who''s tried nothing for themselves and given up."}]},{"type":"heading","attrs":{"level":2,"id":"provide-useful-information"},"content":[{"type":"text","text":"Provide Useful Information"}]},{"type":"paragraph","content":[{"type":"text","text":"If someone is helping you, please reply with more than just \"that doesn''t work\". Show how you followed their advice and what the result was. If you aren''t paying in cash for the help, pay in effort, show people you''ve done as they asked and the exact result of what happened."}]},{"type":"heading","attrs":{"level":2,"id":"make-single-changes"},"content":[{"type":"text","text":"Make Single Changes"}]},{"type":"paragraph","content":[{"type":"text","text":"Change one thing at a time. If more than one person responds, don''t apply more than one suggestion at a time. You need to see what each change does. The exception is when you are explicitly told to apply more than one fix as they can see you have more than one issue. Even then though, it''s just good practice to make a single change and see what it does."}]}]}', 'guide', 1, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, 'Need Help?', 'Learn to ask questions that people want to answer', '[]', '[]', 1698710400000, 1699574400000, 1790346206000);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES
('klustered-winter-2026', 'Klustered Winter 2026 starts 30 October', NULL, 'Klustered returns on Friday, 30 October 2026. Contestants race the clock to diagnose and fix deliberately broken Kubernetes clusters.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Klustered is back. Winter 2026 starts on Friday, 30 October."}]},{"type":"paragraph","content":[{"type":"text","text":"Contestants race against the clock to diagnose and fix deliberately broken Kubernetes clusters. The community can sabotage the clusters, so the rest of us get to watch the troubleshooting unfold live."}]},{"type":"paragraph","content":[{"type":"text","text":"Want to compete? Applications for Winter 2026 are open. Click "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/shows/klustered/apply","target":null,"rel":null,"class":null,"title":null}}],"text":"Apply"},{"type":"text","text":", choose Solo or Team, and sign in to submit your application."}]},{"type":"paragraph","content":[{"type":"text","text":"Put 30 October in your calendar. We’ll see who can get the cluster back on its feet."}]}]}', 'article', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/klustered-winter-2026/cover.webp', 'Connected server racks in a glowing cluster network, with one node fractured by red light', 1734, 907, 'Klustered Winter 2026 starts 30 October', 'The live Kubernetes troubleshooting show returns Friday, 30 October.', '[]', '[]', 1790294400000, NULL, 1790348835000);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES
('kyverno-cel-validating-policy', 'Kyverno ValidatingPolicy with CEL: Working Examples (2026)', NULL, 'Replace ClusterPolicy with Kyverno ValidatingPolicy using CEL expressions. Real examples for image verification, label rules, and replica limits.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kyverno 1.14 (released April 25, 2025) introduces dedicated ValidatingPolicy and ImageValidatingPolicy types that leverage CEL (Common Expression Language) - the same validation language Kubernetes now uses natively, creating a unified policy experience across your entire stack."}]},{"type":"paragraph","content":[{"type":"text","text":"For platform engineers and security teams implementing policy-as-code in Kubernetes, this convergence represents a fundamental shift toward standardization and performance. Let''s explore why this matters and how to get started."}]},{"type":"heading","attrs":{"level":2,"id":"the-cel-convergence"},"content":[{"type":"text","text":"The CEL Convergence"}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes'' adoption of CEL for native validation creates an unprecedented opportunity for policy engines like Kyverno to standardize on the same language. This convergence delivers three critical benefits:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"One expression language"},{"type":"text","text":" to learn across Kubernetes and Kyverno means your team invests in skills that transfer between CRD validation rules, ValidatingAdmissionPolicies, and now Kyverno policies."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Better performance"},{"type":"text","text":" - CEL expressions are parsed once and compiled to bytecode, providing significant speed improvements over traditional validation methods."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Reusable validation logic"},{"type":"text","text":" between native Kubernetes and Kyverno policies eliminates the need to maintain separate validation implementations."}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes now uses CEL in multiple contexts:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CRD validation rules (beta in 1.25, GA in 1.29)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ValidatingAdmissionPolicies (beta in 1.28, GA in 1.30)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Future features like ResourceQuota expressions and RBAC conditions"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This means mastering CEL for Kyverno directly translates to expertise across the entire Kubernetes ecosystem."}]},{"type":"heading","attrs":{"level":2,"id":"your-first-validatingpolicy"},"content":[{"type":"text","text":"Your First ValidatingPolicy"}]},{"type":"paragraph","content":[{"type":"text","text":"Let''s start with a practical example that demonstrates the power and simplicity of Kyverno''s new ValidatingPolicy with CEL:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: policies.kyverno.io/v1alpha1\nkind: ValidatingPolicy\nmetadata:\n  name: require-pod-resources\nspec:\n  matchConstraints:\n    resourceRules:\n    - apiGroups:   [\"\"]\n      apiVersions: [v1]\n      operations:  [CREATE, UPDATE]\n      resources:   [pods]\n  validations:\n  - expression: |\n      object.spec.containers.all(container,\n        has(container.resources.limits) &&\n        has(container.resources.limits.memory) &&\n        has(container.resources.limits.cpu)\n      )\n    message: \"All containers must have CPU and memory limits defined\"\n  - expression: |\n      object.spec.containers.all(container,\n        container.resources.limits.memory.matches(''^[0-9]+(Mi|Gi)$'') &&\n        size(container.resources.limits.memory) <= size(''8Gi'')\n      )\n    message: \"Memory limits must not exceed 8Gi\""}]},{"type":"paragraph","content":[{"type":"text","text":"This policy enforces two critical requirements:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"All containers must have CPU and memory limits defined"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Memory limits cannot exceed 8Gi"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The CEL expressions use familiar functional programming patterns like "},{"type":"text","marks":[{"type":"code"}],"text":"all()"},{"type":"text","text":" to iterate over collections, making the logic both readable and powerful."}]},{"type":"heading","attrs":{"level":2,"id":"why-this-matters-the-kubernetes-cel-native-story"},"content":[{"type":"text","text":"Why This Matters: The Kubernetes CEL Native Story"}]},{"type":"paragraph","content":[{"type":"text","text":"Understanding how CEL fits into the broader Kubernetes ecosystem helps appreciate why this standardization matters. Consider how the same validation logic can now work across different contexts."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"CRD Validation Example:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: apiextensions.k8s.io/v1\nkind: CustomResourceDefinition\nmetadata:\n  name: applications.platform.io\nspec:\n  validation:\n    openAPIV3Schema:\n      properties:\n        spec:\n          properties:\n            replicas:\n              type: integer\n              x-kubernetes-validations:\n              - rule: \"self <= 10\"\n                message: \"replicas cannot exceed 10\""}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Kyverno ValidatingPolicy Example:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: policies.kyverno.io/v1alpha1\nkind: ValidatingPolicy\nmetadata:\n  name: replica-limit\nspec:\n  matchConstraints:\n    resourceRules:\n    - operations: [\"CREATE\", \"UPDATE\"]\n      apiGroups: [\"apps\"]\n      apiVersions: [\"v1\"]\n      resources: [\"deployments\"]\n  validations:\n  - expression: \"object.spec.replicas <= 10\"\n    message: \"replicas cannot exceed 10\""}]},{"type":"paragraph","content":[{"type":"text","text":"Notice how the core CEL expression "},{"type":"text","marks":[{"type":"code"}],"text":"object.spec.replicas <= 10"},{"type":"text","text":" remains identical across all three contexts. This consistency dramatically reduces the learning curve and enables teams to reuse validation logic."}]},{"type":"heading","attrs":{"level":2,"id":"advanced-pattern-cross-resource-validation"},"content":[{"type":"text","text":"Advanced Pattern: Cross-Resource Validation"}]},{"type":"paragraph","content":[{"type":"text","text":"CEL''s power becomes evident when handling complex validation scenarios that require external data or cross-resource relationships:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: policies.kyverno.io/v1alpha1\nkind: ValidatingPolicy\nmetadata:\n  name: namespace-resource-quotas\nspec:\n  matchConstraints:\n    resourceRules:\n    - operations: [\"CREATE\", \"UPDATE\"]\n      apiGroups: [\"apps\"]\n      apiVersions: [\"v1\"]\n      resources: [\"deployments\", \"statefulsets\"]\n  variables:\n  - name: configs\n    expression: >\n      resource.Get(\"v1\", \"configmaps\", \"platform\", \"team-configs\")\n  validations:\n      - expression: |\n          has(object.metadata.labels.team) &&\n          object.metadata.labels.team in variables.configs.data &&\n          object.spec.replicas <= int(variables.configs.data[object.metadata.labels.team])\n        message: \"Replica count exceeds team quota defined in platform/team-configs\"\n      - expression: |\n          has(object.metadata.labels.environment) &&\n          object.metadata.labels.environment in [''dev'', ''staging'', ''prod'']\n        message: \"Must specify valid environment label: dev, staging, or prod\""}]},{"type":"paragraph","content":[{"type":"text","text":"This policy demonstrates advanced CEL patterns:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"External parameter references"},{"type":"text","text":" using "},{"type":"text","marks":[{"type":"code"}],"text":"paramKind"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"code"}],"text":"paramRef"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Data validation"},{"type":"text","text":" against external ConfigMap values"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Multi-expression validation"},{"type":"text","text":" with distinct error messages"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Complex boolean logic"},{"type":"text","text":" combining multiple conditions"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The referenced ConfigMap might look like:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: team-configs\n  namespace: platform\ndata:\n  frontend: \"5\"\n  backend: \"10\"\n  data: \"3\""}]},{"type":"heading","attrs":{"level":2,"id":"imagevalidatingpolicy-in-action"},"content":[{"type":"text","text":"ImageValidatingPolicy in Action"}]},{"type":"paragraph","content":[{"type":"text","text":"Kyverno 1.14 also introduces ImageValidatingPolicy for specialized image security validation:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"# https://github.com/kyverno/policies/blob/main/other/verify-image-ivpol/verify-image-ivpol.yaml\napiVersion: policies.kyverno.io/v1alpha1\nkind: ImageValidatingPolicy\nmetadata:\n  name: verify-image-ivpol\n  annotations:\n    policies.kyverno.io/title: Verify Image\n    policies.kyverno.io/category: Software Supply Chain Security, EKS Best Practices\n    policies.kyverno.io/severity: medium\n    policies.kyverno.io/subject: Pod\n    policies.kyverno.io/minversion: 1.14.0\n    policies.kyverno.io/description: >-\n      Using the Cosign project, OCI images may be signed to ensure supply chain\n      security is maintained. Those signatures can be verified before pulling into\n      a cluster. This policy checks the signature of an image repo called\n      ghcr.io/kyverno/test-verify-image to ensure it has been signed by verifying\n      its signature against the provided public key. This policy serves as an illustration for\n      how to configure a similar rule and will require replacing with your image(s) and keys.\nspec:\n  webhookConfiguration:\n    timeoutSeconds: 30\n  evaluation:\n   background:\n    enabled: false\n  validationActions: [Deny]\n  matchConstraints:\n    resourceRules:\n      - apiGroups: [\"\"]\n        apiVersions: [\"v1\"]\n        operations: [\"CREATE\", \"UPDATE\"]\n        resources: [\"pods\"]\n  matchImageReferences:\n        - glob : \"docker.io/mohdcode/kyverno*\"\n  attestors:\n  - name: cosign\n    cosign:\n     key:\n      data: |\n                -----BEGIN PUBLIC KEY-----\n                MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAE6QsNef3SKYhJVYSVj+ZfbPwJd0pv\n                DLYNHXITZkhIzfE+apcxDjCCkDPcJ3A3zvhPATYOIsCxYPch7Q2JdJLsDQ==\n                -----END PUBLIC KEY-----\n  validations:\n    - expression: >-\n       images.containers.map(image, verifyImageSignatures(image, [attestors.cosign])).all(e ,e > 0)\n      message: >-\n       failed the verification"}]},{"type":"paragraph","content":[{"type":"text","text":"This policy combines signature verification with CEL-based attestation validation, ensuring:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Images are signed with the specified public key"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build provenance follows SLSA standards"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dependencies meet stability requirements"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"migration-guide-from-clusterpolicy-to-validatingpolicy"},"content":[{"type":"text","text":"Migration Guide: From ClusterPolicy to ValidatingPolicy"}]},{"type":"paragraph","content":[{"type":"text","text":"Migrating existing ClusterPolicy resources to the new ValidatingPolicy type often simplifies your policy definitions. Here''s a before/after comparison:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Before (ClusterPolicy):"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: kyverno.io/v1\nkind: ClusterPolicy\nmetadata:\n  name: require-labels\nspec:\n  rules:\n  - name: require-labels\n    match:\n      any:\n      - resources:\n          kinds:\n          - Deployment\n    validate:\n      failureAction: Enforce\n      message: \"Environment label must be dev, staging, or prod\"\n      anyPattern:\n      - metadata:\n          labels:\n            environment: \"dev\" # Changed label key to ''environment'' to match message\n      - metadata:\n          labels:\n            environment: \"staging\"\n      - metadata:\n          labels:\n            environment: \"prod\""}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"After (ValidatingPolicy):"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: policies.kyverno.io/v1alpha1\nkind: ValidatingPolicy\nmetadata:\n  name: require-labels\nspec:\n  matchConstraints:\n    resourceRules:\n    - operations: [\"CREATE\", \"UPDATE\"]\n      apiGroups: [\"apps\"]\n      apiVersions: [\"v1\"]\n      resources: [\"deployments\"]\n  validations:\n    - expression: \"has(object.metadata.labels.team) && object.metadata.labels.team != ''''\"\n      message: \"Deployments must have a team label\"\n    - expression: \"has(object.metadata.labels.environment) && object.metadata.labels.environment in [''dev'', ''staging'', ''prod'']\"\n      message: \"Environment label must be dev, staging, or prod\""}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Migration Benefits:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Reduced complexity"},{"type":"text","text":": Single rule instead of multiple rules"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Better performance"},{"type":"text","text":": CEL compilation vs pattern matching"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Clearer logic"},{"type":"text","text":": Explicit boolean expressions vs pattern inference"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Enhanced readability"},{"type":"text","text":": Self-documenting validation conditions"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"performance-implications"},"content":[{"type":"text","text":"Performance Implications"}]},{"type":"paragraph","content":[{"type":"text","text":"CEL''s compilation model provides significant performance advantages over traditional validation approaches. Kyverno maintainers report substantial improvements in policy evaluation speed, though specific benchmarks vary by workload:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"ClusterPolicy Pattern Matching:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Parse YAML patterns at runtime"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursive object traversal for each validation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Variable performance depending on pattern complexity"}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"ValidatingPolicy CEL:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compile expressions once at policy load"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Direct object field access via compiled bytecode"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Faster execution for complex validation logic"}]}]}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Real-world Impact:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Measurably faster policy evaluation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reduced CPU usage during peak admission loads"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Better cluster responsiveness under policy-heavy workloads"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"For clusters with hundreds of policies and high pod creation rates, these performance improvements directly translate to reduced latency and improved user experience."}]},{"type":"heading","attrs":{"level":2,"id":"getting-started-checklist"},"content":[{"type":"text","text":"Getting Started Checklist"}]},{"type":"paragraph","content":[{"type":"text","text":"Ready to adopt Kyverno 1.14''s ValidatingPolicy? Follow this implementation path:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Upgrade Kyverno"},{"type":"text","text":" to version 1.14 or later"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Start with simple policies"},{"type":"text","text":" using basic CEL expressions"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Gradually migrate"},{"type":"text","text":" existing ClusterPolicy resources"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Leverage external parameters"},{"type":"text","text":" for dynamic validation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Implement ImageValidatingPolicy"},{"type":"text","text":" for supply chain security"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Monitor performance"},{"type":"text","text":" improvements in your cluster"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The convergence of CEL across Kubernetes and Kyverno represents more than just a technical upgrade - it''s a fundamental shift toward a unified policy ecosystem. By adopting these new ValidatingPolicy types, you''re investing in skills and patterns that will serve your platform engineering efforts across the entire Kubernetes landscape."}]},{"type":"paragraph","content":[{"type":"text","text":"Start experimenting with CEL today, and experience the power of unified validation logic across your cloud native stack."}]}]}', 'article', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/kyverno-cel-validating-policy/cover.png', 'Kyverno CEL ValidatingPolicy visualization', 1536, 1024, 'Kyverno ValidatingPolicy with CEL: Working Examples (2026)', 'Migrating from ClusterPolicy with side-by-side examples', '[{"date":"2025-06-04T00:00:00.000Z","description":"Claude article review changed policies for the worst. This has been corrected"}]', '[]', 1748822400000, NULL, 1790346206000);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES
('your-guide-to-kubernetes-dra', 'Your Guide to Kubernetes DRA', NULL, 'Dynamic Resource Allocation lets Kubernetes match device claims to GPU properties. Here is what DRA changes for AI training and inference, and where it still falls short.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"DRA gives Kubernetes a richer device request than a GPU count. Some of the workload-level scheduling that makes this useful is still opt-in."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"nvidia.com/gpu: 8"},{"type":"text","text":" answers one question: how many? It does not, by itself, say which memory profile is acceptable, whether a partitioned device will work, or whether the workers need to fit a particular topology. Teams can encode some of that elsewhere, in node labels, separate resource names or vendor-specific schedulers. Then the hardware request is spread across the platform instead of stated with the workload."}]},{"type":"paragraph","content":[{"type":"text","text":"Dynamic Resource Allocation (DRA) gives Kubernetes a way to describe device requirements as claims and match them to hardware. The practical change is small but important: a workload can ask for a GPU with particular reported properties, not just a number of GPU resources. Here is what that request looks like, and where it still falls short for training and inference."}]},{"type":"heading","attrs":{"level":2,"id":"what-a-claim-tells-the-scheduler"},"content":[{"type":"text","text":"What a claim tells the scheduler"}]},{"type":"paragraph","content":[{"type":"text","text":"The core DRA API has been stable since Kubernetes 1.35. A device driver publishes inventory as "},{"type":"text","marks":[{"type":"code"}],"text":"ResourceSlice"},{"type":"text","text":" objects. A cluster administrator or driver exposes categories through "},{"type":"text","marks":[{"type":"code"}],"text":"DeviceClass"},{"type":"text","text":". A workload uses a "},{"type":"text","marks":[{"type":"code"}],"text":"ResourceClaim"},{"type":"text","text":", or a "},{"type":"text","marks":[{"type":"code"}],"text":"ResourceClaimTemplate"},{"type":"text","text":" when each Pod should get its own similar claim. The scheduler finds a matching device and places the Pod on a node that can access it; the node-local driver then prepares the device for the container. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/docs/concepts/resource-management/dynamic-resource-allocation/","target":null,"rel":null,"class":null,"title":null}}],"text":"Kubernetes describes DRA as a claims-based allocation API, similar in shape to claiming storage through a PersistentVolumeClaim."}]},{"type":"paragraph","content":[{"type":"text","text":"This template selects a device advertised as a GPU with exactly 64Gi of memory:"}]},{"type":"codeBlock","attrs":{"language":"yaml","title":null,"meta":null},"content":[{"type":"text","text":"apiVersion: resource.k8s.io/v1\nkind: ResourceClaimTemplate\nmetadata:\n  name: example-gpu-template\nspec:\n  spec:\n    devices:\n      requests:\n      - name: gpu\n        exactly:\n          deviceClassName: example-device-class\n          selectors:\n          - cel:\n              expression: |-\n                device.attributes[\"driver.example.com\"].type == \"gpu\" &&\n                device.capacity[\"driver.example.com\"].memory == quantity(\"64Gi\")"}]},{"type":"paragraph","content":[{"type":"text","text":"The example class and attribute names come from the installed driver and cluster configuration. The equality matters: this matches exactly 64Gi as reported by the driver. It does not mean “at least 64Gi”, and it does not carve 64Gi out of a larger GPU. A Pod references the template; its container references the resulting claim. Kubernetes can then compare that request with the device inventory before starting the workload. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/docs/tasks/configure-pod-container/assign-resources/allocate-devices-dra/","target":null,"rel":null,"class":null,"title":null}}],"text":"The official task shows the full claim-to-Pod flow."}]},{"type":"heading","attrs":{"level":2,"id":"training-is-a-group-placement-problem-too"},"content":[{"type":"text","text":"Training is a group-placement problem too"}]},{"type":"paragraph","content":[{"type":"text","text":"If a training job needs eight workers before it can make progress, scheduling four and leaving four pending can tie up GPUs without starting useful work. Gang scheduling addresses that by placing a configured minimum number of Pods as a group. Set "},{"type":"text","marks":[{"type":"code"}],"text":"minCount"},{"type":"text","text":" to eight when all eight are required. This is an initial scheduling guarantee, not a promise that all workers become ready together or that the group can never shrink after a deletion or eviction."}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes 1.37 also lets a Workload or PodGroup reference a DRA claim shared by its member Pods. That is useful when the group shares a resource; it is not shorthand for a separate GPU allocation for every worker. Model each worker''s accelerator needs explicitly, then use group scheduling for the all-or-nothing placement requirement."}]},{"type":"paragraph","content":[{"type":"text","text":"Both paths are Beta and disabled by default in Kubernetes 1.37. Gang scheduling uses the "},{"type":"text","marks":[{"type":"code"}],"text":"GenericWorkload"},{"type":"text","text":" feature gate; shared DRA workload claims use "},{"type":"text","marks":[{"type":"code"}],"text":"DRAWorkloadResourceClaims"},{"type":"text","text":". Topology-aware workload scheduling is still Alpha, so a claim does not by itself guarantee placement on a particular rack or fabric. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/09/08/kubernetes-v1-37-advancing-workload-aware-scheduling/","target":null,"rel":null,"class":null,"title":null}}],"text":"The 1.37 scheduling update spells out the feature gates and current boundaries."}]},{"type":"heading","attrs":{"level":2,"id":"inference-needs-a-fallback-not-a-traffic-router"},"content":[{"type":"text","text":"Inference needs a fallback, not a traffic router"}]},{"type":"paragraph","content":[{"type":"text","text":"Serving fleets may have more than one acceptable accelerator class. DRA lets the platform define those classes and match device properties. Kubernetes 1.36 made prioritised device lists stable, so a request can prefer one device class and fall back to another. That can make otherwise-idle capacity usable, but it does not make the devices equivalent. Different replicas can receive different alternatives, so test the fallback against the model''s serving target. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/05/07/kubernetes-v1-36-dra-136-updates/","target":null,"rel":null,"class":null,"title":null}}],"text":"The Kubernetes 1.36 DRA update describes prioritised selection."}]},{"type":"paragraph","content":[{"type":"text","text":"And this is still placement, not request routing. DRA does not choose which replica handles an HTTP request, autoscale a model server or enforce a latency objective. Those remain responsibilities of the serving and autoscaling layers."}]},{"type":"heading","attrs":{"level":2,"id":"existing-pod-requests-can-stay-put"},"content":[{"type":"text","text":"Existing Pod requests can stay put"}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes 1.37 made it stable for DRA to satisfy traditional extended-resource requests. A Pod can keep asking for a resource through "},{"type":"text","marks":[{"type":"code"}],"text":"resources.requests"},{"type":"text","text":", while the scheduler allocates a matching DRA device behind that name. This gives platform teams a way to move allocation logic without first changing every workload manifest. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/09/03/kubernetes-v1-37-dra-updates/","target":null,"rel":null,"class":null,"title":null}}],"text":"The Kubernetes 1.37 DRA update documents the compatibility path."}]},{"type":"paragraph","content":[{"type":"text","text":"That is manifest compatibility, not an automatic migration. For NVIDIA''s legacy "},{"type":"text","marks":[{"type":"code"}],"text":"nvidia.com/gpu"},{"type":"text","text":" name, the GPU Operator requires a separate "},{"type":"text","marks":[{"type":"code"}],"text":"DeviceClass"},{"type":"text","text":" with "},{"type":"text","marks":[{"type":"code"}],"text":"spec.extendedResourceName"},{"type":"text","text":" set to that name. Its 26.7 "},{"type":"text","marks":[{"type":"code"}],"text":"GPUCluster"},{"type":"text","text":" workflow also does not support in-place migration from "},{"type":"text","marks":[{"type":"code"}],"text":"ClusterPolicy"},{"type":"text","text":" or a standalone DRA driver installation. Check the driver and operator''s actual migration path before promising a no-disruption switch. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/26.7/dra-intro-install.html","target":null,"rel":null,"class":null,"title":null}}],"text":"NVIDIA documents these prerequisites and limitations."}]},{"type":"heading","attrs":{"level":2,"id":"the-driver-still-decides-what-the-claim-means"},"content":[{"type":"text","text":"The driver still decides what the claim means"}]},{"type":"paragraph","content":[{"type":"text","text":"DRA is a Kubernetes API and scheduler integration, not a universal accelerator driver. The driver has to publish useful properties and do whatever preparation the hardware needs. The runtime and vendor stack still have to make the allocated device available inside the container. NVIDIA''s current GPU Operator DRA instructions, for example, require Kubernetes 1.34.2 or later, GPU driver 580 or later, and a CDI-capable runtime configured for CDI injection."}]},{"type":"paragraph","content":[{"type":"text","text":"Sharing also depends on the driver and device. DRA can coordinate supported sharing, but it does not make a sharing mode fair or isolated by itself. Core DRA is stable; several workload and fine-grained capacity features are still Beta or feature-gated. Check the state of the specific capability you plan to use, not just the headline API."}]},{"type":"heading","attrs":{"level":2,"id":"a-useful-first-test"},"content":[{"type":"text","text":"A useful first test"}]},{"type":"paragraph","content":[{"type":"text","text":"Pick one serving workload and one training job. Ask the driver which attributes it publishes, then make a claim that should match and one that should not. Check the allocated device and confirm the container can use it. For the training job, test the 1.37 PodGroup and DRA gates separately in a non-production cluster, and make the topology requirement explicit."}]},{"type":"paragraph","content":[{"type":"text","text":"If the scheduler cannot match the request to a real device, or the container cannot use the allocation it receives, DRA has not yet made that hardware contract useful. That is the test to pass before turning a new claim schema into a platform promise."}]},{"type":"heading","attrs":{"level":2,"id":"references"},"content":[{"type":"text","text":"References"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/docs/concepts/resource-management/dynamic-resource-allocation/","target":null,"rel":null,"class":null,"title":null}}],"text":"Dynamic Resource Allocation concepts"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/docs/tasks/configure-pod-container/assign-resources/allocate-devices-dra/","target":null,"rel":null,"class":null,"title":null}}],"text":"Allocate devices to workloads with DRA"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/05/07/kubernetes-v1-36-dra-136-updates/","target":null,"rel":null,"class":null,"title":null}}],"text":"Kubernetes 1.36 DRA updates"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/09/03/kubernetes-v1-37-dra-updates/","target":null,"rel":null,"class":null,"title":null}}],"text":"Kubernetes 1.37 DRA updates"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/09/08/kubernetes-v1-37-advancing-workload-aware-scheduling/","target":null,"rel":null,"class":null,"title":null}}],"text":"Kubernetes 1.37 workload-aware scheduling"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/26.7/dra-intro-install.html","target":null,"rel":null,"class":null,"title":null}}],"text":"NVIDIA GPU Operator DRA prerequisites"}]}]}]}]}', 'tutorial', 0, 0, NULL, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 1790294400000, NULL, 1790346175000);
INSERT INTO `articles` (`id`, `title`, `subtitle`, `description`, `body`, `type`, `howto`, `draft`, `series`, `categories`, `tags`, `cover_url`, `cover_alt`, `cover_width`, `cover_height`, `open_graph_title`, `open_graph_subtitle`, `updates`, `resources`, `published_at`, `revised_at`, `updated_at`) VALUES
('zed-show-and-tell', 'Zed: Show & Tell', NULL, 'Explore Zed, a fast and modern code editor written in Rust with collaborative features', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A common habit of developers is searching for new tools on a regular basis. Visual Studio Code is such a tool which helped me over the years write some awesome code. But I always wanted to try something new. So I stumbled upon Zed."}]},{"type":"heading","attrs":{"level":2,"id":"so-what-is-zed"},"content":[{"type":"text","text":"So what is Zed?"}]},{"type":"paragraph","content":[{"type":"text","text":"Zed is a fairly new code editor written in Rust by the awesome folks which created tools like "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/atom/atom","target":null,"rel":null,"class":null,"title":null}}],"text":"Atom"},{"type":"text","text":". It got open sourced in the beginning of 2024. Zed aims to be a fast, collaborative and hackable editor. But have a look for yourself "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/zed-industries/zed","target":null,"rel":null,"class":null,"title":null}}],"text":"here"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"I personally really like that it comes with a lot of "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/zed-industries/zed/tree/main/extensions","target":null,"rel":null,"class":null,"title":null}}],"text":"extensions"},{"type":"text","text":" and "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://zed.dev/docs/vim","target":null,"rel":null,"class":null,"title":null}}],"text":"\"vim mode\""},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2,"id":"installation"},"content":[{"type":"text","text":"Installation"}]},{"type":"paragraph","content":[{"type":"text","text":"You could build Zed either from source or download a pre-compiled binary (only macOS is currently supported)."}]},{"type":"paragraph","content":[{"type":"text","text":"I personally used "},{"type":"text","marks":[{"type":"code"}],"text":"brew"},{"type":"text","text":" to install Zed: "},{"type":"text","marks":[{"type":"code"}],"text":"brew install zed"}]},{"type":"heading","attrs":{"level":2,"id":"lets-open-a-project"},"content":[{"type":"text","text":"Let''s open a project"}]},{"type":"paragraph","content":[{"type":"text","text":"The first thing you see is an empty window. I typically use "},{"type":"text","marks":[{"type":"code"}],"text":"⌘ + P"},{"type":"text","text":" to open the file finder and navigate to my file of choice."}]},{"type":"image","attrs":{"src":"https://content.rawkode.academy/articles/zed-show-and-tell/zed-show-and-tell-01.png","alt":"Zed - empty window","title":null,"width":2672,"height":1420,"darkSrc":null,"zoomable":true}},{"type":"paragraph","content":[{"type":"text","text":"Here you see the file finder in action."}]},{"type":"image","attrs":{"src":"https://content.rawkode.academy/articles/zed-show-and-tell/zed-show-and-tell-02.png","alt":"Zed - file finder","title":null,"width":2672,"height":1420,"darkSrc":null,"zoomable":true}},{"type":"heading","attrs":{"level":2,"id":"working-with-rust"},"content":[{"type":"text","text":"Working with Rust"}]},{"type":"paragraph","content":[{"type":"text","text":"Zed is \"language aware\" and detected that I opened a Rust file and applies the correct syntax highlighting. The "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://zed.dev/docs/languages/rust","target":null,"rel":null,"class":null,"title":null}}],"text":"Rust extension"},{"type":"text","text":" is shipped with Zed by default. The extension uses "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/rust-lang/rust-analyzer","target":null,"rel":null,"class":null,"title":null}}],"text":"rust-analyzer"},{"type":"text","text":" for things like code completion, running tests and "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/tree-sitter/tree-sitter-rust","target":null,"rel":null,"class":null,"title":null}}],"text":"tree-sitter-rust"},{"type":"text","text":" for syntax highlighting. It also added indicators for Rust tests, so that I can run them directly from the editor. Let''s try it out :)"}]},{"type":"image","attrs":{"src":"https://content.rawkode.academy/articles/zed-show-and-tell/zed-show-and-tell-03.png","alt":"Zed - rust file","title":null,"width":2672,"height":1420,"darkSrc":null,"zoomable":true}},{"type":"paragraph","content":[{"type":"text","text":"After clicking the \"Run\" button (the little \"play\" icon next to the test function), the test output is displayed in the built-in terminal at the bottom of the window."}]},{"type":"image","attrs":{"src":"https://content.rawkode.academy/articles/zed-show-and-tell/zed-show-and-tell-04.png","alt":"Zed - rust test","title":null,"width":2672,"height":1420,"darkSrc":null,"zoomable":true}},{"type":"paragraph","content":[{"type":"text","text":"Let''s do some refactoring. I open the "},{"type":"text","marks":[{"type":"code"}],"text":"editor: rename"},{"type":"text","text":" option (via Command Palette) by pressing "},{"type":"text","marks":[{"type":"code"}],"text":"⌘ + Shift + P"},{"type":"text","text":", change the name of the variable and see all changes in some kind of preview window."}]},{"type":"image","attrs":{"src":"https://content.rawkode.academy/articles/zed-show-and-tell/zed-show-and-tell-05.png","alt":"Zed - refactoring","title":null,"width":2672,"height":1420,"darkSrc":null,"zoomable":true}},{"type":"heading","attrs":{"level":2,"id":"conclusion"},"content":[{"type":"text","text":"Conclusion"}]},{"type":"paragraph","content":[{"type":"text","text":"Coming from Visual Studio Code, knowing its key bindings and what not, the transition to Zed was quite a smooth ride. I used it for 2 weeks to write some Rust and TypeScript and did not miss too much. I will definitely stick with Visual Studio Code for now, because some extensions e.g. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://github.com/evrensen467/zed-sql","target":null,"rel":null,"class":null,"title":null}}],"text":"zed-sql"},{"type":"text","text":" is still behind what the Visual Studio Code ecosystem offers."}]},{"type":"paragraph","content":[{"type":"text","text":"Things I haven''t yet tried are the AI integration and the collaboration features, but I will definitely give them a try in the future."}]},{"type":"paragraph","content":[{"type":"text","text":"I''m very happy with the overall experience so far and I''m looking forward to a bright future for Zed."}]}]}', 'article', 0, 0, NULL, '[]', '[]', 'https://content.rawkode.academy/articles/zed-show-and-tell/zed-show-and-tell-cover.png', 'zed website', 1574, 769, 'A New Editor in Town', 'A modern code editor, written in Rust', '[]', '[]', 1720137600000, NULL, 1790346206000);
